      api_lifecycle_admission: Docking_Access_Supervisor.AdmissionDecision): B =
    {
      val r0 = compute_case_NO_REQUEST(In_requestLedger, requestLedger, api_request_facts, api_lifecycle_admission)
      val r1 = compute_case_INVALID_REQUEST(In_requestLedger, requestLedger, api_request_facts, api_lifecycle_admission)
      val r2 = compute_case_FRESH_DOCK_ACCEPTED(In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_vessel_readiness, api_lifecycle_admission)
      val r3 = compute_case_DUPLICATE_DOCK(In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_lifecycle_admission)
      val r4 = compute_case_DOCK_NOT_READY(In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_vessel_readiness, api_lifecycle_admission)
      val r5 = compute_case_DOCK_DEFERRED(In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_lifecycle_admission)
      val r6 = compute_case_ACCESS_PARTITION(In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_service_readiness, api_lifecycle_admission)
      val r7 = compute_case_UNDOCK_PARTITION(In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_service_readiness, api_lifecycle_admission)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7
    }

  /** CEP-Post: Compute Entrypoint Post-Condition for request_admission
    *
    * @param In_requestLedger pre-state state variable
    * @param requestLedger post-state state variable
    * @param api_admission_guard incoming data port
