    * @param api_lifecycle_admission outgoing data port
    * @param api_request_disposition outgoing data port
    * @param api_undocking_admission outgoing data port
    */
  @strictpure def compute_CEP_Post (
      In_requestLedger: Docking_Access_Supervisor.RequestLedger.Type,
      requestLedger: Docking_Access_Supervisor.RequestLedger.Type,
      api_admission_guard: Docking_Access_Supervisor.AdmissionGuard,
      api_request_facts: Docking_Access_Supervisor.RequestFacts,
      api_service_readiness: Docking_Access_Supervisor.ServiceFacts,
      api_vessel_readiness: Docking_Access_Supervisor.VesselFacts,
