      val r0 = compute_CEP_T_Guar (api_access_admission, api_docking_admission, api_gate_admission, api_lifecycle_admission, api_request_disposition, api_undocking_admission)

      // CEP-T-Case: case clauses of request_admission's compute entrypoint
      val r1 = compute_CEP_T_Case (In_requestLedger, requestLedger, api_admission_guard, api_request_facts, api_service_readiness, api_vessel_readiness, api_lifecycle_admission)

      r0 & r1
    }

